SELECT 'Tabla trueno', 'Tablas', 'pixelmon:zap_plate', 300, 2, 2 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM rotom_mine_rewards WHERE item_id = 'pixelmon:zap_plate');

